  2→// Receives form data via POST, sends email notification, returns JSON response
  3→//
  4→// Environment variables needed in Cloudflare Pages settings:
  5→//   RESEND_API_KEY — API key from resend.com (free tier: 100 emails/day)
  6→//   NOTIFY_EMAIL  — where to send notifications (default: Info@AreoCore.com)
  7→
  8→export async function onRequestPost(context) {
  9→  const headers = {
 10→    'Content-Type': 'application/json',
 11→    'Access-Control-Allow-Origin': '*',
 12→  };
 13→
 14→  try {
 15→    const body = await context.request.json();
 16→
 17→    // Basic validation
 18→    if (!body.name || !body.email) {
 19→      return new Response(JSON.stringify({ ok: false, error: 'Name and email are required.' }), {
 20→        status: 400,
 21→        headers,
 22→      });
 23→    }
 24→
 25→    // Simple email format check
 26→    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
 27→      return new Response(JSON.stringify({ ok: false, error: 'Invalid email address.' }), {
 28→        status: 400,
 29→        headers,
 30→      });
 31→    }
 32→
 33→    // Honeypot check — if _gotcha field is filled, it's a bot
 34→    if (body._gotcha) {
 35→      return new Response(JSON.stringify({ ok: true }), { status: 200, headers });
 36→    }
 37→
 38→    const notifyEmail = context.env.NOTIFY_EMAIL || 'Info@AreoCore.com';
 39→    const apiKey = context.env.RESEND_API_KEY;
 40→
 41→    // Build email body
 42→    const lines = [
 43→      `Name: ${body.name}`,
 44→      `Company: ${body.company || '—'}`,
 45→      `Email: ${body.email}`,
 46→      `Phone: ${body.phone || '—'}`,
 47→      `Material: ${body.material || '—'}`,
 48→      `Details: ${body.details || '—'}`,
 49→      `Source Page: ${body.source || '—'}`,
 50→    ];
 51→
 52→    if (body.utm && Object.keys(body.utm).length > 0) {
 53→      lines.push('', '--- Ad Attribution ---');
 54→      Object.entries(body.utm).forEach(([k, v]) => lines.push(`${k}: ${v}`));
 55→    }
 56→
 57→    lines.push('', `Submitted: ${new Date().toISOString()}`);
 58→
 59→    const textBody = lines.join('\n');
 60→
 61→    // Send via Resend if API key is configured
 62→    if (apiKey) {
 63→      const emailRes = await fetch('https://api.resend.com/emails', {
 64→        method: 'POST',
 65→        headers: {
 66→          'Authorization': `Bearer ${apiKey}`,
 67→          'Content-Type': 'application/json',
 68→        },
 69→        body: JSON.stringify({
 70→          from: 'AeroCore Quotes <quotes@areocore.com>',
 71→          to: [notifyEmail],
 72→          reply_to: body.email,
 73→          subject: `Quote Request from ${body.name}${body.company ? ' (' + body.company + ')' : ''}`,
 74→          text: textBody,
 75→        }),
 76→      });
 77→
 78→      if (!emailRes.ok) {
 79→        console.error('Resend API error:', await emailRes.text());
 80→        return new Response(JSON.stringify({ ok: false, error: 'Failed to send notification.' }), {
 81→          status: 500,
 82→          headers,
 83→        });
 84→      }
 85→    } else {
 86→      // No email API configured — log to console (visible in Cloudflare dashboard logs)
 87→      console.log('QUOTE SUBMISSION (no email API configured):', textBody);
 88→    }
 89→
 90→    return new Response(JSON.stringify({ ok: true }), { status: 200, headers });
 91→  } catch (err) {
