 33→    const to = params.get('to') || null;
 34→    const page = Math.max(1, parseInt(params.get('page'), 10) || 1);
 35→    const perPage = Math.min(200, Math.max(1, parseInt(params.get('perPage'), 10) || 50));
 36→    const offset = (page - 1) * perPage;
 37→
