 50→      const pattern = `%${q}%`;
 51→      bindings.push(pattern, pattern, pattern);
 52→    }
 53→
 54→    if (from) {
 55→      conditions.push('s.created_at >= ?');
 56→      bindings.push(from);
 57→    }
